17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        List<String> missingFields = new ArrayList<>();
106	        if (isBlank(ownerFieldsDto.getFirstName())) {
107	            missingFields.add("firstName");
108	        }
109	        if (isBlank(ownerFieldsDto.getLastName())) {
110	            missingFields.add("lastName");
111	        }
112	        if (isBlank(ownerFieldsDto.getAddress())) {
113	            missingFields.add("address");
114	        }
115	        if (isBlank(ownerFieldsDto.getCity())) {
116	            missingFields.add("city");
117	        }
118	        if (isBlank(ownerFieldsDto.getTelephone())) {
119	            missingFields.add("telephone");
120	        }
121	        if (!missingFields.isEmpty()) {
122	            throw new InvalidOwnerFieldsException(missingFields);
123	        }
124	        // Normalize the telephone by stripping every non-digit character; it must
125	        // contain exactly 10 digits afterwards, otherwise the request is rejected.
126	        String normalizedTelephone = ownerFieldsDto.getTelephone().replaceAll("\\D", "");
127	        if (normalizedTelephone.length() != 10) {
128	            throw new InvalidOwnerFieldsException(List.of("telephone"));
129	        }
130	        // Reject the request if the normalized telephone is already used by any other owner.
131	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
132	            .map(Owner::getTelephone)
133	            .filter(existing -> existing != null)
134	            .map(existing -> existing.replaceAll("\\D", ""))
135	            .anyMatch(normalizedTelephone::equals);
136	        if (telephoneInUse) {
137	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
138	        }
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        owner.setTelephone(normalizedTelephone);
142	        this.clinicService.saveOwner(owner);
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
152	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
153	        if (currentOwner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        currentOwner.setAddress(ownerFieldsDto.getAddress());
157	        currentOwner.setCity(ownerFieldsDto.getCity());
158	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
159	        currentOwner.setLastName(ownerFieldsDto.getLastName());
160	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
161	        this.clinicService.saveOwner(currentOwner);
162	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Transactional
167	    @Override
168	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        this.clinicService.deleteOwner(owner);
174	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        HttpHeaders headers = new HttpHeaders();
185	        Pet pet = petMapper.toPet(petFieldsDto);
186	        owner.setId(ownerId);
187	        pet.setOwner(owner);
188	        pet.getType().setName(null);
189	        this.clinicService.savePet(pet);
190	        PetDto petDto = petMapper.toPetDto(pet);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
192	            .buildAndExpand(pet.getId()).toUri());
193	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
199	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
200	        if (currentOwner != null) {
201	            Pet currentPet = this.clinicService.findPetById(petId);
202	            if (currentPet != null) {
203	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
204	                currentPet.setName(petFieldsDto.getName());
205	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
206	                this.clinicService.savePet(currentPet);
207	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	            }
209	        }
210	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	    }
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
216	        HttpHeaders headers = new HttpHeaders();
217	        Visit visit = visitMapper.toVisit(visitFieldsDto);
218	        Pet pet = new Pet();
219	        pet.setId(petId);
220	        visit.setPet(pet);
221	        this.clinicService.saveVisit(visit);
222	        VisitDto visitDto = visitMapper.toVisitDto(visit);
223	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
224	            .buildAndExpand(visit.getId()).toUri());
225	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
226	    }
227	
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
232	        Owner owner = this.clinicService.findOwnerById(ownerId);
233	        if (owner != null) {
234	            Pet pet = owner.getPet(petId);
235	            if (pet != null) {
236	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
241	
242	    private static boolean isBlank(String value) {
243	        return value == null || value.trim().isEmpty();
244	    }
245	}
